// ── Foreign-buyer SEO landing data ────────────────────────────────────────
// Powers /buying-property-in-dubai-as/[citizen] programmatic pages.
// Long-form fields are localized (en/ru/ar/zh/vi/he); slug/country/citizen/
// flag/preferredAreas are language-neutral.

export type LocalizedText = { en: string; fr: string; ru: string; ar: string; zh: string; vi: string; he: string };

export interface ForeignBuyerProfile {
  slug: string;
  country: string;
  citizen: string;
  flag: string;
  intro: LocalizedText;
  whyDubai: LocalizedText;
  legalStatus: LocalizedText;
  financing: LocalizedText;
  taxImplications: LocalizedText;
  repatriation: LocalizedText;
  preferredAreas: string[];
}

export function localizeBuyerText(t: LocalizedText, locale: string): string {
  return t[locale as keyof LocalizedText] ?? t.en;
}

